function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 5;
  gameState = 'PLAYING';

  player.x = 192;
  player.y = 376;

  cars = [];
  let numLanes = 10;
  let laneHeight = 32;
  let startY = 40;

  for (let i = 0; i < numLanes; i++) {
    let laneY = startY + i * laneHeight;
    let speed = 1.5 + rng() * 3.5; // Speed 1.5 to 5.0
    let dir = rng() > 0.5 ? 1 : -1;
    let numCars = Math.floor(rng() * 3) + 1; // 1 to 3 cars per lane
    let carLen = 30 + rng() * 40; // Length 30 to 70
    let spacing = width / numCars;

    for (let j = 0; j < numCars; j++) {
      let startX = j * spacing + rng() * (spacing - carLen);
      cars.push({
        x: startX,
        y: laneY + (laneHeight - 16) / 2, // Centered in lane
        w: carLen,
        h: 16,
        speed: speed,
        dir: dir
      });
    }
  }
}
